document.querySelector("#batch39 .grid").insertAdjacentHTML("beforeend","<a class=\"card\" href=\"summaries/mahmoud-15455379.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف شلة الأنس\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة تجارية</span><h3>شلة الأنس</h3><p>تضع النبذة شخصيات شلة الأنس في لقاءات شعبية تتجاور فيها الأحاديث اليومية والأحلام. ومن أمثلتها طموح ليمو العجلاتي إلى صنع صاروخ، بجوار رغبات أقرب…</p><small>مصطفى محمود</small></a><a class=\"card\" href=\"summaries/mahmoud-15455387.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف عنبر 7\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة تجارية</span><h3>عنبر 7</h3><p>تعرّف النبذة عنبر 7 بعمل قصصي تتوسطه تجربة المرض والإقامة في المستشفى. داخل هذا المكان تتجاور هشاشة الجسد وعلاقات النزلاء وأسئلة الإنسان عن حياته…</p><small>مصطفى محمود</small></a><a class=\"card\" href=\"summaries/mahmoud-15455344.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف ألعاب السيرك السياسي\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة تجارية</span><h3>ألعاب السيرك السياسي</h3><p>تعرض نبذة الطبعة ألعاب السيرك السياسي كمقالات نقدية في العلاقات الدولية، مع حضور لحرب الخليج ودور القوى الكبرى في الأزمات. يستخدم مصطفى محمود نظر…</p><small>مصطفى محمود</small></a>");
